mapper.select:
select  from ord_dir_order_allocation_pool_history where 1 = 1

    and store_code = #{storeCode}


    and store_code in

        #{item}



    and store_name like concat('%',#{storeName},'%')


    and goods_code = #{goodsCode}


    and goods_name like concat('%',#{goodsName},'%')


    and status = #{status}


    and supplement_quantity ${operation} #{supplementQuantity}


    and truncation_date_time between #{truncationDateTimeBegin} and #{truncationDateTimeEnd}


    and biz_org_code = #{bizOrgCode}

order by truncation_date_time  desc,store_code desc ,supplement_quantity desc
